import{_ as e,o as i,c as o,a3 as s}from"./chunks/framework.B5WAEDB7.js";const r="/assets/images/OfVllex.png",m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"study-guide.md","filePath":"study-guide.md"}'),n={name:"study-guide.md"};function d(a,t,g,h,u,l){return i(),o("div",null,[...t[0]||(t[0]=[s('<h2 id="study-guide" tabindex="-1">Study guide <a class="header-anchor" href="#study-guide" aria-label="Permalink to &quot;Study guide&quot;">​</a></h2><blockquote><p>Suggested topics to review based on your interview timeline (short, medium, long).</p></blockquote><p><img src="'+r+'" alt="Imgur"></p><p><strong>Q: For interviews, do I need to know everything here?</strong></p><p><strong>A: No, you don&#39;t need to know everything here to prepare for the interview</strong>.</p><p>What you are asked in an interview depends on variables such as:</p><ul><li>How much experience you have</li><li>What your technical background is</li><li>What positions you are interviewing for</li><li>Which companies you are interviewing with</li><li>Luck</li></ul><p>More experienced candidates are generally expected to know more about system design. Architects or team leads might be expected to know more than individual contributors. Top tech companies are likely to have one or more design interview rounds.</p><p>Start broad and go deeper in a few areas. It helps to know a little about various key system design topics. Adjust the following guide based on your timeline, experience, what positions you are interviewing for, and which companies you are interviewing with.</p><ul><li><strong>Short timeline</strong> - Aim for <strong>breadth</strong> with system design topics. Practice by solving <strong>some</strong> interview questions.</li><li><strong>Medium timeline</strong> - Aim for <strong>breadth</strong> and <strong>some depth</strong> with system design topics. Practice by solving <strong>many</strong> interview questions.</li><li><strong>Long timeline</strong> - Aim for <strong>breadth</strong> and <strong>more depth</strong> with system design topics. Practice by solving <strong>most</strong> interview questions.</li></ul><table tabindex="0"><thead><tr><th></th><th>Short</th><th>Medium</th><th>Long</th></tr></thead><tbody><tr><td>Read through the <a href="#index-of-system-design-topics">System design topics</a> to get a broad understanding of how systems work</td><td>👍</td><td>👍</td><td>👍</td></tr><tr><td>Read through a few articles in the <a href="#company-engineering-blogs">Company engineering blogs</a> for the companies you are interviewing with</td><td>👍</td><td>👍</td><td>👍</td></tr><tr><td>Read through a few <a href="#real-world-architectures">Real world architectures</a></td><td>👍</td><td>👍</td><td>👍</td></tr><tr><td>Review <a href="#how-to-approach-a-system-design-interview-question">How to approach a system design interview question</a></td><td>👍</td><td>👍</td><td>👍</td></tr><tr><td>Work through <a href="#system-design-interview-questions-with-solutions">System design interview questions with solutions</a></td><td>Some</td><td>Many</td><td>Most</td></tr><tr><td>Work through <a href="#object-oriented-design-interview-questions-with-solutions">Object-oriented design interview questions with solutions</a></td><td>Some</td><td>Many</td><td>Most</td></tr><tr><td>Review <a href="#additional-system-design-interview-questions">Additional system design interview questions</a></td><td>Some</td><td>Many</td><td>Most</td></tr></tbody></table>',11)])])}const p=e(n,[["render",d]]);export{m as __pageData,p as default};
